exec("import json\nimport os\nimport re\n\nimport uvicorn\nfrom fastapi import Body, FastAPI\nfrom fastapi.responses import HTMLResponse\nfrom openai import OpenAI\n\n\napp = FastAPI(title=\"Senwanshan AI Short Video Tool\")\n\nAPI_KEY = os.getenv(\"API_KEY\", \"\")\nBASE_URL = os.getenv(\"BASE_URL\", \"https://api.deepseek.com\")\nMODEL = os.getenv(\"MODEL\", \"deepseek-chat\")\nTEMPERATURE = float(os.getenv(\"TEMPERATURE\", \"0.8\"))\n\nSYSTEM_PROMPT = \"\"\"\nYou are a Douyin short-video viral content strategist.\nAlways write in Simplified Chinese.\nOptimize for the first 5 seconds completion rate, comments, saves, shares, emotion, and practical value.\nUse one main emotion from: xue mai jue xing, yi chu ji feng, duo ba an shuang gan, da po lv jing, chao jue song chi gan, huan xing zi yu, chong su nei he, huai jiu meng he.\nUse natural emotion words, identity words, pain-point words, and value words. Do not make the writing stiff.\nReturn valid JSON only.\n\"\"\"\n\n\ndef call_model(task, payload, schema):\n    if not API_KEY:\n        return {\n            \"error\": \"API_KEY is missing. Add your model provider key in the deployment environment variables.\"\n        }\n    client = OpenAI(api_key=API_KEY, base_url=BASE_URL)\n    user_prompt = (\n        f\"Task: {task}\\n\\nInput:\\n\"\n        f\"{json.dumps(payload, ensure_ascii=False)}\\n\\n\"\n        f\"Return JSON with this shape:\\n{schema}\"\n    )\n    try:\n        result = client.chat.completions.create(\n            model=MODEL,\n            messages=[\n                {\"role\": \"system\", \"content\": SYSTEM_PROMPT},\n                {\"role\": \"user\", \"content\": user_prompt},\n            ],\n            temperature=TEMPERATURE,\n            max_tokens=4096,\n        )\n        return parse_json(result.choices[0].message.content or \"\")\n    except Exception as exc:\n        return {\"error\": str(exc)}\n\n\ndef parse_json(text):\n    text = re.sub(r\"```(?:json)?\", \"\", text).replace(\"```\", \"\").strip()\n    for left, right in [(\"[\", \"]\"), (\"{\", \"}\")]:\n        start = text.find(left)\n        end = text.rfind(right)\n        if start >= 0 and end > start:\n            try:\n                return json.loads(text[start : end + 1])\n            except Exception:\n                pass\n    return {\"content\": text}\n\n\n@app.get(\"/\")\nasync def home():\n    return HTMLResponse(HTML)\n\n\n@app.get(\"/health\")\nasync def health():\n    return {\n        \"status\": \"ok\",\n        \"model\": MODEL,\n        \"base_url\": BASE_URL,\n        \"api_key_configured\": bool(API_KEY),\n    }\n\n\n@app.post(\"/api/generate/viral-topic\")\nasync def viral_topic(data: dict = Body(default={})):\n    schema = \"\"\"\n[\n {\"title\":\"\", \"score\":\"8-10\", \"emotional_type\":\"\", \"hook\":\"\", \"reason\":\"\", \"script_brief\":\"\", \"viral_rating\":{\"five_second_completion\":9,\"comment_desire\":9,\"save_value\":9,\"emotion_resonance\":9}, \"comment_hook\":\"\", \"angle\":\"\"}\n]\n\"\"\"\n    return {\"success\": True, \"content\": call_model(\"Generate 5 viral Douyin topic ideas.\", data, schema)}\n\n\n@app.post(\"/api/generate/monetization-topic\")\nasync def monetization_topic(data: dict = Body(default={})):\n    schema = \"\"\"\n[\n {\"title\":\"\", \"score\":\"8-10\", \"purchase_driver\":\"\", \"emotional_type\":\"\", \"script_brief\":\"\", \"angle\":\"\", \"call_to_action\":\"\"}\n]\n\"\"\"\n    return {\"success\": True, \"content\": call_model(\"Generate 5 high-conversion short-video ideas.\", data, schema)}\n\n\n@app.post(\"/api/generate/script\")\nasync def script(data: dict = Body(default={})):\n    schema = \"\"\"\n{\"title\":\"\",\"main_emotion\":\"\",\"duration\":\"\",\"hook\":\"\",\"structure\":[{\"role\":\"\",\"time\":\"\",\"content\":\"\",\"visual\":\"\",\"behavior_target\":\"\",\"emotion_words\":\"\",\"mindset_words\":\"\"}],\"closing\":\"\",\"tips\":[],\"comment_hook\":\"\"}\n\"\"\"\n    return {\"success\": True, \"content\": call_model(\"Write a complete Douyin video script.\", data, schema)}\n\n\n@app.post(\"/api/generate/copy-rewrite\")\nasync def copy_rewrite(data: dict = Body(default={})):\n    schema = \"\"\"\n[\n {\"title\":\"\", \"angle\":\"\", \"main_emotion\":\"\", \"content\":\"\", \"emotion_words\":[], \"mindset_words\":[], \"comment_hook\":\"\"}\n]\n\"\"\"\n    return {\"success\": True, \"content\": call_model(\"Rewrite the copy into 3 viral versions.\", data, schema)}\n\n\n@app.post(\"/api/generate/video-analysis\")\nasync def video_analysis(data: dict = Body(default={})):\n    schema = \"\"\"\n{\"summary\":\"\",\"viral_points\":[],\"emotion_strategy\":\"\",\"weaknesses\":[],\"rewrite_hook\":\"\",\"rewrite_direction\":\"\",\"comment_hook\":\"\"}\n\"\"\"\n    return {\"success\": True, \"content\": call_model(\"Analyze and improve a viral video idea.\", data, schema)}\n\n\nHTML = \"\"\"\n<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>\\u68ee\\u4e07\\u5c71\\u77ed\\u89c6\\u9891\\u7b56\\u7565\\u53f0</title>\n<style>\n:root{\n  --bg:#f5f6f8;\n  --panel:#ffffff;\n  --panel-soft:#fafbfc;\n  --line:#dfe3ea;\n  --line-strong:#c8d0dc;\n  --text:#1d2633;\n  --muted:#687386;\n  --accent:#087f5b;\n  --accent-soft:#e8f7f1;\n  --accent-line:#a8dfc9;\n  --blue:#2459c6;\n  --amber:#9a5b00;\n  --danger:#b42318;\n  --shadow:0 10px 28px rgba(29,38,51,.07);\n}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--text);font-family:\"Microsoft YaHei\",\"PingFang SC\",Arial,sans-serif}\nbutton,input,textarea{font:inherit}\n.shell{min-height:100vh;display:grid;grid-template-columns:252px minmax(0,1fr)}\n.side{background:var(--panel);border-right:1px solid var(--line);padding:18px 14px;position:sticky;top:0;height:100vh}\n.brand{display:flex;align-items:center;gap:10px;padding:8px 8px 18px;border-bottom:1px solid var(--line)}\n.mark{width:34px;height:34px;border:1px solid var(--line-strong);border-radius:8px;display:grid;place-items:center;background:linear-gradient(135deg,#f7fff9,#eef4ff);font-weight:800;color:var(--accent)}\n.brand strong{display:block;font-size:16px;line-height:1.2}.brand span{display:block;color:var(--muted);font-size:12px;margin-top:3px}\n.nav{display:grid;gap:8px;margin-top:18px}\n.nav button{height:48px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--text);display:flex;align-items:center;justify-content:space-between;padding:0 12px;cursor:pointer;text-align:left}\n.nav button:hover{background:var(--panel-soft);border-color:var(--line)}\n.nav button.active{background:var(--accent-soft);border-color:var(--accent-line);color:var(--accent);font-weight:700}\n.nav small{font-size:11px;color:var(--muted);font-weight:500}\n.sideFoot{position:absolute;left:14px;right:14px;bottom:18px;border-top:1px solid var(--line);padding-top:14px;color:var(--muted);font-size:12px;line-height:1.7}\n.main{min-width:0;padding:22px 24px 28px}\n.top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:18px}\n.headline h1{margin:0;font-size:26px;line-height:1.25;letter-spacing:0}.headline p{margin:8px 0 0;color:var(--muted);font-size:14px;max-width:760px}\n.status{display:flex;align-items:center;gap:10px;border:1px solid var(--line);background:var(--panel);border-radius:8px;padding:10px 12px;color:var(--muted);box-shadow:var(--shadow);white-space:nowrap}\n.dot{width:8px;height:8px;border-radius:99px;background:var(--accent)}\n.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:18px}\n.metric{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:13px 14px;min-height:74px}\n.metric b{display:block;font-size:20px;line-height:1.1}.metric span{display:block;color:var(--muted);font-size:12px;margin-top:8px}\n.workspace{display:grid;grid-template-columns:minmax(360px,440px) minmax(0,1fr);gap:18px;align-items:start}\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px;box-shadow:var(--shadow)}\n.panelHead{padding:18px 18px 12px;border-bottom:1px solid var(--line);display:flex;align-items:flex-start;justify-content:space-between;gap:12px}\n.panelHead h2{margin:0;font-size:19px;line-height:1.25}.panelHead p{margin:6px 0 0;color:var(--muted);font-size:13px;line-height:1.5}\n.tag{border:1px solid var(--line);border-radius:999px;background:var(--panel-soft);padding:5px 9px;color:var(--muted);font-size:12px;white-space:nowrap}\n.formBody{padding:16px 18px 18px}\n.field{margin-bottom:14px}.field label{display:flex;justify-content:space-between;gap:10px;margin-bottom:7px;color:#354052;font-size:13px;font-weight:700}\n.field label span{font-weight:500;color:var(--muted)}\ntextarea{width:100%;min-height:94px;resize:vertical;border:1px solid var(--line-strong);border-radius:8px;background:#fff;padding:11px 12px;color:var(--text);line-height:1.55;outline:none}\ntextarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(8,127,91,.12)}\n.actions{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-top:16px}\n.leftActions,.rightActions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}\n.btn{height:38px;border-radius:8px;border:1px solid var(--line-strong);background:#fff;color:var(--text);padding:0 13px;cursor:pointer}\n.btn:hover{border-color:#9aa7b8;background:var(--panel-soft)}\n.btn.primary{border-color:var(--accent);background:var(--accent);color:#fff;font-weight:700;min-width:104px}\n.btn.primary:disabled{opacity:.65;cursor:not-allowed}\n.hint{font-size:12px;color:var(--muted);line-height:1.6;margin-top:10px}\n.resultBody{padding:16px 18px;min-height:520px}\n.empty,.loading,.error{border:1px solid var(--line);border-radius:8px;background:var(--panel-soft);padding:18px;color:var(--muted);line-height:1.7}\n.loading{border-color:var(--accent-line);background:var(--accent-soft);color:#255f4a}\n.error{border-color:#f5b5ae;background:#fff3f1;color:var(--danger)}\n.resultList{display:grid;gap:12px}\n.item{border:1px solid var(--line);border-radius:8px;background:#fff;overflow:hidden}\n.itemTop{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;background:var(--panel-soft);border-bottom:1px solid var(--line);padding:12px 14px}\n.itemTitle{font-weight:800;line-height:1.45}.score{color:var(--blue);font-size:12px;white-space:nowrap;padding-top:2px}\n.kv{display:grid;gap:8px;padding:12px 14px}\n.kv div{display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;line-height:1.65;font-size:14px}\n.kv b{color:var(--muted);font-size:12px;font-weight:700;padding-top:2px}\n.jsonBlock{white-space:pre-wrap;word-break:break-word;margin:0;padding:13px 14px;background:#20262f;color:#eef2f7;font-size:13px;line-height:1.65}\n.copyRow{display:flex;justify-content:flex-end;padding:10px 14px;border-top:1px solid var(--line);background:#fff}\n.toast{position:fixed;right:22px;bottom:22px;background:#1f2937;color:#fff;border-radius:8px;padding:10px 13px;box-shadow:var(--shadow);opacity:0;transform:translateY(10px);transition:.2s}\n.toast.show{opacity:1;transform:translateY(0)}\n@media(max-width:1050px){\n  .shell{grid-template-columns:1fr}.side{position:relative;height:auto;border-right:0;border-bottom:1px solid var(--line)}.sideFoot{position:static;margin-top:14px}.nav{grid-template-columns:repeat(5,minmax(120px,1fr));overflow:auto}.workspace,.metrics{grid-template-columns:1fr}.top{flex-direction:column}\n}\n@media(max-width:640px){\n  .main{padding:16px}.nav{grid-template-columns:1fr}.metrics{gap:8px}.metric{min-height:64px}.workspace{gap:12px}.panelHead{display:block}.tag{display:inline-block;margin-top:10px}.actions{align-items:stretch;flex-direction:column}.leftActions,.rightActions{width:100%}.btn{flex:1}.kv div{grid-template-columns:1fr;gap:2px}\n}\n</style>\n</head>\n<body>\n<div class=\"shell\">\n  <aside class=\"side\">\n    <div class=\"brand\">\n      <div class=\"mark\">SW</div>\n      <div><strong>\\u68ee\\u4e07\\u5c71\\u7b56\\u7565\\u53f0</strong><span>\\u77ed\\u89c6\\u9891\\u9009\\u9898\\u4e0e\\u811a\\u672c\\u751f\\u4ea7</span></div>\n    </div>\n    <nav class=\"nav\" id=\"tabs\"></nav>\n    <div class=\"sideFoot\">\n      <div>\\u6a21\\u578b\\uff1a\\u767e\\u70bc / qwen-plus</div>\n      <div>\\u72b6\\u6001\\uff1a\\u5df2\\u8fde\\u63a5\\u751f\\u4ea7\\u73af\\u5883</div>\n    </div>\n  </aside>\n  <main class=\"main\">\n    <div class=\"top\">\n      <div class=\"headline\">\n        <h1>\\u77ed\\u89c6\\u9891\\u5185\\u5bb9\\u751f\\u4ea7\\u5de5\\u4f5c\\u53f0</h1>\n        <p>\\u628a\\u4eba\\u7fa4\\u3001\\u4e3b\\u9898\\u3001\\u60c5\\u7eea\\u548c\\u5356\\u70b9\\u8f93\\u5165\\u8fdb\\u53bb\\uff0c\\u76f4\\u63a5\\u4ea7\\u51fa\\u53ef\\u62cd\\u6444\\u3001\\u53ef\\u590d\\u76d8\\u3001\\u53ef\\u4fdd\\u5b58\\u7684\\u5185\\u5bb9\\u65b9\\u6848\\u3002</p>\n      </div>\n      <div class=\"status\"><span class=\"dot\"></span><span id=\"modelStatus\">\\u767e\\u70bc\\u6a21\\u578b\\u5728\\u7ebf</span></div>\n    </div>\n    <div class=\"metrics\">\n      <div class=\"metric\"><b>5</b><span>\\u751f\\u4ea7\\u6a21\\u5757</span></div>\n      <div class=\"metric\"><b>JSON</b><span>\\u7ed3\\u6784\\u5316\\u8f93\\u51fa</span></div>\n      <div class=\"metric\"><b>\\u4e2d\\u6587</b><span>\\u9ed8\\u8ba4\\u5185\\u5bb9\\u8bed\\u8a00</span></div>\n      <div class=\"metric\"><b>\\u5373\\u7528</b><span>\\u90e8\\u7f72\\u73af\\u5883\\u5df2\\u63a5\\u5165</span></div>\n    </div>\n    <div class=\"workspace\">\n      <section class=\"panel\">\n        <div class=\"panelHead\">\n          <div><h2 id=\"title\"></h2><p id=\"subtitle\"></p></div>\n          <span class=\"tag\" id=\"tag\"></span>\n        </div>\n        <div class=\"formBody\">\n          <div id=\"form\"></div>\n          <div class=\"actions\">\n            <div class=\"leftActions\">\n              <button class=\"btn\" type=\"button\" onclick=\"fillSample()\">\\u586b\\u5165\\u793a\\u4f8b</button>\n              <button class=\"btn\" type=\"button\" onclick=\"clearForm()\">\\u6e05\\u7a7a</button>\n            </div>\n            <div class=\"rightActions\">\n              <button class=\"btn primary\" id=\"generateBtn\" type=\"button\" onclick=\"go()\">\\u751f\\u6210\\u65b9\\u6848</button>\n            </div>\n          </div>\n          <div class=\"hint\" id=\"hint\"></div>\n        </div>\n      </section>\n      <section class=\"panel\">\n        <div class=\"panelHead\">\n          <div><h2>\\u8f93\\u51fa\\u7ed3\\u679c</h2><p id=\"resultHint\">\\u751f\\u6210\\u540e\\u4f1a\\u5728\\u8fd9\\u91cc\\u663e\\u793a\\u53ef\\u76f4\\u63a5\\u4f7f\\u7528\\u7684\\u5185\\u5bb9\\u3002</p></div>\n          <button class=\"btn\" type=\"button\" onclick=\"copyResult()\">\\u590d\\u5236\\u7ed3\\u679c</button>\n        </div>\n        <div class=\"resultBody\">\n          <div id=\"result\" class=\"empty\">\\u5148\\u9009\\u62e9\\u5de6\\u4fa7\\u6a21\\u5757\\uff0c\\u586b\\u5165\\u4fe1\\u606f\\u540e\\u751f\\u6210\\u3002</div>\n        </div>\n      </section>\n    </div>\n  </main>\n</div>\n<div class=\"toast\" id=\"toast\">\\u5df2\\u590d\\u5236</div>\n<script>\nconst tabs={\n viral:{name:\"\\u7206\\u6b3e\\u9009\\u9898\",code:\"TOPIC\",url:\"/api/generate/viral-topic\",subtitle:\"\\u7528\\u4e8e\\u6279\\u91cf\\u751f\\u6210\\u6709\\u94a9\\u5b50\\u3001\\u6709\\u60c5\\u7eea\\u3001\\u6709\\u8bc4\\u8bba\\u70b9\\u7684\\u9009\\u9898\\u3002\",hint:\"\\u9002\\u5408\\u6bcf\\u5929\\u505a\\u9009\\u9898\\u6c60\\u3001\\u8d26\\u53f7\\u5b9a\\u4f4d\\u6d4b\\u8bd5\\u3001\\u7cfb\\u5217\\u5185\\u5bb9\\u89c4\\u5212\\u3002\",fields:[[\"industry\",\"\\u884c\\u4e1a / \\u4eba\\u7fa4\",\"\\u4f8b\\uff1aAI\\u77ed\\u89c6\\u9891\\u521b\\u4f5c\\u8005\\uff0c\\u76ee\\u6807\\u4eba\\u7fa4\\u662f\\u60f3\\u9760\\u5185\\u5bb9\\u53d8\\u73b0\\u7684\\u65b0\\u624b\\u535a\\u4e3b\"],[\"main_type\",\"\\u4e3b\\u811a\\u672c\\u7c7b\\u578b\",\"\\u4f8b\\uff1a\\u53e3\\u64ad + \\u6848\\u4f8b\\u62c6\\u89e3\"],[\"sub_type\",\"\\u7ec6\\u5206\\u65b9\\u5411\",\"\\u4f8b\\uff1a\\u6da8\\u7c89\\u9009\\u9898\"],[\"elements\",\"\\u7206\\u6b3e\\u5143\\u7d20\",\"\\u4f8b\\uff1a\\u7126\\u8651, \\u723d\\u611f, \\u53cd\\u5dee, \\u53ef\\u4fdd\\u5b58, \\u8bc4\\u8bba\\u4e89\\u8bae\"]],sample:{industry:\"AI\\u77ed\\u89c6\\u9891\\u521b\\u4f5c\\u8005\\uff0c\\u76ee\\u6807\\u4eba\\u7fa4\\u662f\\u60f3\\u9760\\u5185\\u5bb9\\u53d8\\u73b0\\u7684\\u65b0\\u624b\\u535a\\u4e3b\",main_type:\"\\u53e3\\u64ad + \\u6848\\u4f8b\\u62c6\\u89e3\",sub_type:\"\\u6da8\\u7c89\\u9009\\u9898\",elements:\"\\u7126\\u8651, \\u723d\\u611f, \\u53cd\\u5dee, \\u53ef\\u4fdd\\u5b58, \\u8bc4\\u8bba\\u4e89\\u8bae\"}},\n money:{name:\"\\u53d8\\u73b0\\u9009\\u9898\",code:\"MONEY\",url:\"/api/generate/monetization-topic\",subtitle:\"\\u7528\\u4e8e\\u628a\\u5185\\u5bb9\\u65b9\\u5411\\u8f6c\\u6210\\u66f4\\u5bb9\\u6613\\u6210\\u4ea4\\u3001\\u79c1\\u4fe1\\u6216\\u8f6c\\u5316\\u7684\\u9009\\u9898\\u3002\",hint:\"\\u9002\\u5408\\u8bfe\\u7a0b\\u3001\\u54a8\\u8be2\\u3001\\u5de5\\u5177\\u3001\\u8d44\\u6599\\u5305\\u3001\\u793e\\u7fa4\\u548c\\u670d\\u52a1\\u578b\\u8d26\\u53f7\\u3002\",fields:[[\"industry\",\"\\u884c\\u4e1a / \\u4ea7\\u54c1\",\"\\u4f8b\\uff1aAI\\u526a\\u8f91\\u8bfe\\uff0c\\u9762\\u5411\\u96f6\\u57fa\\u7840\\u526f\\u4e1a\\u4eba\\u7fa4\"],[\"main_type\",\"\\u4e3b\\u811a\\u672c\\u7c7b\\u578b\",\"\\u4f8b\\uff1a\\u75db\\u70b9\\u53e3\\u64ad + \\u7ed3\\u679c\\u8bc1\\u660e\"],[\"sub_type\",\"\\u8f6c\\u5316\\u65b9\\u5411\",\"\\u4f8b\\uff1a\\u5f15\\u5bfc\\u79c1\\u4fe1\\u9886\\u53d6\\u8d44\\u6599\"],[\"elements\",\"\\u8d2d\\u4e70\\u7406\\u7531\",\"\\u4f8b\\uff1a\\u7701\\u65f6\\u95f4, \\u964d\\u95e8\\u69db, \\u6709\\u6a21\\u677f, \\u5feb\\u901f\\u89c1\\u7ed3\\u679c\"]],sample:{industry:\"AI\\u526a\\u8f91\\u8bfe\\uff0c\\u9762\\u5411\\u96f6\\u57fa\\u7840\\u526f\\u4e1a\\u4eba\\u7fa4\",main_type:\"\\u75db\\u70b9\\u53e3\\u64ad + \\u7ed3\\u679c\\u8bc1\\u660e\",sub_type:\"\\u5f15\\u5bfc\\u79c1\\u4fe1\\u9886\\u53d6\\u8d44\\u6599\",elements:\"\\u7701\\u65f6\\u95f4, \\u964d\\u95e8\\u69db, \\u6709\\u6a21\\u677f, \\u5feb\\u901f\\u89c1\\u7ed3\\u679c\"}},\n script:{name:\"\\u811a\\u672c\\u751f\\u6210\",code:\"SCRIPT\",url:\"/api/generate/script\",subtitle:\"\\u7528\\u4e8e\\u628a\\u9009\\u9898\\u6269\\u5c55\\u6210\\u5b8c\\u6574\\u53e3\\u64ad\\u811a\\u672c\\u548c\\u5206\\u955c\\u7ed3\\u6784\\u3002\",hint:\"\\u9002\\u5408\\u628a\\u5355\\u6761\\u9009\\u9898\\u5feb\\u901f\\u53d8\\u6210\\u53ef\\u62cd\\u6444\\u811a\\u672c\\u3002\",fields:[[\"topic\",\"\\u9009\\u9898\",\"\\u4f8b\\uff1a\\u666e\\u901a\\u4eba\\u5982\\u4f55\\u7528AI\\u4e00\\u5929\\u505a\\u51fa10\\u6761\\u77ed\\u89c6\\u9891\"],[\"industry\",\"\\u884c\\u4e1a / \\u4eba\\u7fa4\",\"\\u4f8b\\uff1a\\u77e5\\u8bc6\\u535a\\u4e3b\\uff0c\\u7c89\\u4e1d\\u57281\\u4e07\\u4ee5\\u5185\"],[\"requirements\",\"\\u811a\\u672c\\u8981\\u6c42\",\"\\u4f8b\\uff1a60\\u79d2\\uff0c\\u524d3\\u79d2\\u5f3a\\u94a9\\u5b50\\uff0c\\u7ed3\\u5c3e\\u5f15\\u5bfc\\u8bc4\\u8bba\\u9886\\u53d6\\u6a21\\u677f\"]],sample:{topic:\"\\u666e\\u901a\\u4eba\\u5982\\u4f55\\u7528AI\\u4e00\\u5929\\u505a\\u51fa10\\u6761\\u77ed\\u89c6\\u9891\",industry:\"\\u77e5\\u8bc6\\u535a\\u4e3b\\uff0c\\u7c89\\u4e1d\\u57281\\u4e07\\u4ee5\\u5185\",requirements:\"60\\u79d2\\uff0c\\u524d3\\u79d2\\u5f3a\\u94a9\\u5b50\\uff0c\\u7ed3\\u5c3e\\u5f15\\u5bfc\\u8bc4\\u8bba\\u9886\\u53d6\\u6a21\\u677f\"}},\n rewrite:{name:\"\\u6587\\u6848\\u6539\\u5199\",code:\"REWRITE\",url:\"/api/generate/copy-rewrite\",subtitle:\"\\u7528\\u4e8e\\u628a\\u539f\\u6587\\u6848\\u6539\\u6210\\u66f4\\u6709\\u60c5\\u7eea\\u3001\\u66f4\\u50cf\\u77ed\\u89c6\\u9891\\u7206\\u6b3e\\u8868\\u8fbe\\u3002\",hint:\"\\u9002\\u5408\\u6539\\u6807\\u9898\\u3001\\u53e3\\u64ad\\u7a3f\\u3001\\u670b\\u53cb\\u5708\\u6216\\u79c1\\u57df\\u8f6c\\u5316\\u6587\\u6848\\u3002\",fields:[[\"text\",\"\\u539f\\u59cb\\u6587\\u6848\",\"\\u4f8b\\uff1a\\u6211\\u4eec\\u6709\\u4e00\\u5957AI\\u77ed\\u89c6\\u9891\\u5de5\\u5177\\uff0c\\u53ef\\u4ee5\\u5e2e\\u4f60\\u5feb\\u901f\\u751f\\u6210\\u9009\\u9898\\u548c\\u811a\\u672c\\u3002\"],[\"style\",\"\\u6539\\u5199\\u65b9\\u5411\",\"\\u4f8b\\uff1a\\u66f4\\u6709\\u51b2\\u7a81\\u611f\\uff0c\\u66f4\\u9002\\u5408\\u6296\\u97f3\\u53e3\\u64ad\\uff0c\\u4fdd\\u7559\\u771f\\u5b9e\\u611f\"]],sample:{text:\"\\u6211\\u4eec\\u6709\\u4e00\\u5957AI\\u77ed\\u89c6\\u9891\\u5de5\\u5177\\uff0c\\u53ef\\u4ee5\\u5e2e\\u4f60\\u5feb\\u901f\\u751f\\u6210\\u9009\\u9898\\u548c\\u811a\\u672c\\u3002\",style:\"\\u66f4\\u6709\\u51b2\\u7a81\\u611f\\uff0c\\u66f4\\u9002\\u5408\\u6296\\u97f3\\u53e3\\u64ad\\uff0c\\u4fdd\\u7559\\u771f\\u5b9e\\u611f\"}},\n analysis:{name:\"\\u89c6\\u9891\\u590d\\u76d8\",code:\"ANALYSIS\",url:\"/api/generate/video-analysis\",subtitle:\"\\u7528\\u4e8e\\u5206\\u6790\\u4e00\\u4e2a\\u89c6\\u9891\\u60f3\\u6cd5\\u6216\\u5df2\\u6709\\u89c6\\u9891\\u63cf\\u8ff0\\uff0c\\u62c6\\u51fa\\u53ef\\u4f18\\u5316\\u70b9\\u3002\",hint:\"\\u9002\\u5408\\u590d\\u76d8\\u7206\\u6b3e\\u3001\\u62c6\\u7ade\\u54c1\\u3001\\u6539\\u81ea\\u5df1\\u7684\\u65e7\\u5185\\u5bb9\\u3002\",fields:[[\"url\",\"\\u89c6\\u9891\\u94fe\\u63a5\",\"\\u4f8b\\uff1ahttps://example.com/video\"],[\"description\",\"\\u89c6\\u9891\\u63cf\\u8ff0\",\"\\u4f8b\\uff1a\\u89c6\\u9891\\u8bb2\\u666e\\u901a\\u4eba\\u7528AI\\u505a\\u526f\\u4e1a\\uff0c\\u5f00\\u5934\\u5c55\\u793a\\u6536\\u76ca\\u622a\\u56fe\\uff0c\\u4e2d\\u95f4\\u8bb2\\u5de5\\u5177\\u6d41\\u7a0b\\u3002\"]],sample:{url:\"https://example.com/video\",description:\"\\u89c6\\u9891\\u8bb2\\u666e\\u901a\\u4eba\\u7528AI\\u505a\\u526f\\u4e1a\\uff0c\\u5f00\\u5934\\u5c55\\u793a\\u6536\\u76ca\\u622a\\u56fe\\uff0c\\u4e2d\\u95f4\\u8bb2\\u5de5\\u5177\\u6d41\\u7a0b\\u3002\"}}\n};\nlet current=\"viral\";\nlet latestResult=\"\";\nconst tabsEl=document.getElementById(\"tabs\");\nconst titleEl=document.getElementById(\"title\");\nconst subtitleEl=document.getElementById(\"subtitle\");\nconst tagEl=document.getElementById(\"tag\");\nconst formEl=document.getElementById(\"form\");\nconst resultEl=document.getElementById(\"result\");\nconst hintEl=document.getElementById(\"hint\");\nconst generateBtn=document.getElementById(\"generateBtn\");\nfunction esc(s){return String(s??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]))}\nfunction drawTabs(){\n  tabsEl.innerHTML=Object.entries(tabs).map(([k,v])=>`<button class=\"${k===current?'active':''}\" type=\"button\" onclick=\"setTab('${k}')\"><span>${v.name}</span><small>${v.code}</small></button>`).join(\"\");\n}\nfunction setTab(key){current=key;drawTabs();drawForm();resetResult();}\nfunction drawForm(){\n  const t=tabs[current];\n  titleEl.textContent=t.name;\n  subtitleEl.textContent=t.subtitle;\n  tagEl.textContent=t.code;\n  hintEl.textContent=t.hint;\n  formEl.innerHTML=t.fields.map(([k,l,p])=>`<div class=\"field\"><label for=\"${k}\">${l}<span>${k===\"elements\"?\"\\u9017\\u53f7\\u5206\\u9694\":\"\"}</span></label><textarea id=\"${k}\" placeholder=\"${esc(p)}\"></textarea></div>`).join(\"\");\n}\nfunction resetResult(){\n  latestResult=\"\";\n  resultEl.className=\"empty\";\n  resultEl.textContent=\"\\u5148\\u9009\\u62e9\\u5de6\\u4fa7\\u6a21\\u5757\\uff0c\\u586b\\u5165\\u4fe1\\u606f\\u540e\\u751f\\u6210\\u3002\";\n}\nfunction fillSample(){\n  const sample=tabs[current].sample;\n  for(const [key] of tabs[current].fields){\n    const el=document.getElementById(key);\n    if(el) el.value=sample[key]||\"\";\n  }\n}\nfunction clearForm(){\n  for(const [key] of tabs[current].fields){\n    const el=document.getElementById(key);\n    if(el) el.value=\"\";\n  }\n  resetResult();\n}\nasync function go(){\n  const t=tabs[current];\n  const data={};\n  for(const [key] of t.fields){\n    const value=document.getElementById(key).value.trim();\n    data[key]=key===\"elements\"?value.split(/[,\\uff0c]/).map(x=>x.trim()).filter(Boolean):value;\n  }\n  resultEl.className=\"loading\";\n  resultEl.textContent=\"\\u6b63\\u5728\\u751f\\u6210\\uff0c\\u8bf7\\u7a0d\\u7b49...\";\n  generateBtn.disabled=true;\n  generateBtn.textContent=\"\\u751f\\u6210\\u4e2d\";\n  try{\n    const response=await fetch(t.url,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(data)});\n    const json=await response.json();\n    const content=json.content||json;\n    if(content&&content.error){showError(content.error);return}\n    show(content);\n  }catch(error){\n    showError(error.message||\"\\u8bf7\\u6c42\\u5931\\u8d25\");\n  }finally{\n    generateBtn.disabled=false;\n    generateBtn.textContent=\"\\u751f\\u6210\\u65b9\\u6848\";\n  }\n}\nfunction showError(message){\n  latestResult=String(message||\"\");\n  resultEl.className=\"error\";\n  resultEl.innerHTML=`<strong>\\u751f\\u6210\\u5931\\u8d25</strong><br>${esc(latestResult)}`;\n}\nfunction valueRows(obj){\n  const labels={score:\"\\u7206\\u6b3e\\u8bc4\\u5206\",emotional_type:\"\\u60c5\\u7eea\\u7c7b\\u578b\",hook:\"\\u5f00\\u5934\\u94a9\\u5b50\",reason:\"\\u63a8\\u8350\\u7406\\u7531\",script_brief:\"\\u811a\\u672c\\u7b80\\u8ff0\",comment_hook:\"\\u8bc4\\u8bba\\u5f15\\u5bfc\",angle:\"\\u5207\\u5165\\u89d2\\u5ea6\",purchase_driver:\"\\u8d2d\\u4e70\\u9a71\\u52a8\",call_to_action:\"\\u8f6c\\u5316\\u52a8\\u4f5c\",main_emotion:\"\\u4e3b\\u60c5\\u7eea\",duration:\"\\u65f6\\u957f\",closing:\"\\u7ed3\\u5c3e\",summary:\"\\u603b\\u7ed3\",rewrite_hook:\"\\u6539\\u5199\\u94a9\\u5b50\",rewrite_direction:\"\\u6539\\u5199\\u65b9\\u5411\"};\n  return Object.entries(obj).filter(([k])=>k!==\"title\").slice(0,8).map(([k,v])=>`<div><b>${esc(labels[k]||k)}</b><span>${esc(typeof v===\"string\"?v:JSON.stringify(v,null,2))}</span></div>`).join(\"\");\n}\nfunction show(content){\n  latestResult=JSON.stringify(content,null,2);\n  resultEl.className=\"\";\n  if(Array.isArray(content)){\n    resultEl.innerHTML=`<div class=\"resultList\">${content.map((item,index)=>renderItem(item,index)).join(\"\")}</div>`;\n    return;\n  }\n  if(content&&typeof content===\"object\"){\n    resultEl.innerHTML=renderItem(content,0);\n    return;\n  }\n  resultEl.innerHTML=`<pre class=\"jsonBlock\">${esc(content)}</pre>`;\n}\nfunction renderItem(item,index){\n  const title=item&&item.title?item.title:`\\u7ed3\\u679c ${index+1}`;\n  const score=item&&item.score?`\\u8bc4\\u5206 ${item.score}`:\"\";\n  return `<article class=\"item\"><div class=\"itemTop\"><div class=\"itemTitle\">${esc(title)}</div><div class=\"score\">${esc(score)}</div></div><div class=\"kv\">${valueRows(item||{})}</div><pre class=\"jsonBlock\">${esc(JSON.stringify(item,null,2))}</pre></article>`;\n}\nasync function copyResult(){\n  if(!latestResult){toast(\"\\u6682\\u65e0\\u7ed3\\u679c\");return}\n  try{await navigator.clipboard.writeText(latestResult);toast(\"\\u5df2\\u590d\\u5236\\u7ed3\\u679c\")}catch(e){toast(\"\\u590d\\u5236\\u5931\\u8d25\")}\n}\nfunction toast(text){\n  const el=document.getElementById(\"toast\");\n  el.textContent=text;\n  el.classList.add(\"show\");\n  setTimeout(()=>el.classList.remove(\"show\"),1500);\n}\ndrawTabs();\ndrawForm();\n</script>\n</body>\n</html>\n\"\"\"\n\n\nif __name__ == \"__main__\":\n    port = int(os.getenv(\"PORT\", \"9100\"))\n    uvicorn.run(app, host=\"0.0.0.0\", port=port)\n")
